function V.buffCopies(Ct,Dt)
Dt=tonumber(Dt)or tonumber(Ct.cd)or 60
local Et=math.max(1,tonumber(Ct.time)or 30)
local Ft=math.max(1,math.ceil(Dt/Et-0.001))
local Gt=V.stackCap(Ct.attack)
if Gt then
local Ht=0
for It,Jt in pairs(Ct.types or{})do
Ht=math.max(Ht,tonumber(Jt)or 0)
end
if Ht>0 then
local Kt=1
while Kt<6 and(1+Ht)^Kt-1<Gt-0.02 do
Kt=Kt+1
end
Ft=math.max(Ft,math.ceil(Kt*math.max(1,Dt/Et)-0.001))
end
end
return Ft
end
