return nil
end
local ux={weak={},strong={},res={}}
for vx,xx in pairs(type(tx._weak_against)==CBe[2159]and tx._weak_against or type(tx.weak_against)==CBe[2159]and tx.weak_against or{})do
local yx=type(xx)==CBe[2159]and xx.damage_type or(type(xx)==CBe[1064]and xx)or nil
