ux.weak[yx]=type(xx)==CBe[2159]and W.weakAmp(xx.amplification)or 1.5
end
end
for zx,Ax in pairs(type(tx._strong_against)==CBe[2159]and tx._strong_against or type(tx.strong_against)==CBe[2159]and tx.strong_against or{})do
local Bx=type(Ax)==CBe[2159]and Ax.damage_type or(type(Ax)==CBe[1064]and Ax)or nil
local Cx,Dx=type(Ax)==CBe[2159]and tonumber(Ax.amplification),type(Ax)==CBe[2159]and tonumber(Ax.resistance)
if Bx then
if Dx then
ux.res[Bx]=100/(100+Dx)
elseif Cx and Cx<1 then
ux.res[Bx]=Cx
else
ux.strong[Bx]=true
end
end
end
return(next(ux.weak)or next(ux.strong)or next(ux.res))and ux or nil
end
