end
F.log(1,CBe[2673],string.format(CBe[2776],tI-oI(),(tonumber(((N.prof().capsule_pity_data or{})[mb.STAR]or{}).total_opens)or 0)))
ab.pickNote.skins=nil
elseif uI.open>0 then
local yI=uI.open>=10 and 10 or 1
local zI=tonumber(N.cur(CBe[2733]))or 0
local AI,BI=F.request(CBe[2777],CBe[2778],mb.STAR,CBe[2182],CBe[2779],tostring(yI))
while U.now()-vI<5 and oI()<=0 do
