function W.needsHelp(MP)
local NP,OP=pcall(W.sim,MP)
if NP and type(OP)==CBe[2159]and tonumber(OP.p)~=nil then
return tonumber(OP.p)<0.5
end
local PP,QP=pcall(W.rec,MP.key)
return PP and type(QP)==CBe[2159]and(tonumber(QP.streak)or 0)>=2 or false
end
W.MATCHED_DAILY_P=0.7
function W.icWinP(RP)
local SP=RP.rec or W.rec(RP.key)
local TP=W.icLost(RP.room)
local UP=TP and TP.n or 0
local VP=((tonumber(SP.wins)or 0)+(RP.p0 or W.PRIOR_WIN.castle)*2)/((tonumber(SP.runs)or 0)+2)
local WP=W.sim(RP)
local XP,YP=0,0
if WP and tonumber(WP.p)then
local ZP=type(WP.trust)==CBe[2159]and WP.trust or nil
local _P=ZP~=nil and not ZP.ok
local aQ=_P and(tonumber(ZP.ratio)or 1)>1
if not _P or(aQ and not WP.won)or(_P and not aQ and WP.won)then
local bQ,cQ=pcall(gb.styleP,WP)
XP,YP=(bQ and tonumber(cQ))or tonumber(WP.p),W.IC.SIM_W
end
end
return(VP*2+XP*YP)/(UP+2+YP)
end
function W.winP(dQ)
if dQ.kind==CBe[2618]then
return W.icWinP(dQ)
end
if dQ.kind==CBe[2616]and O.dailyMatch and not O.dailyLoop then
local eQ,fQ=pcall(W.needsHelp,dQ)
if eQ and fQ then
return W.MATCHED_DAILY_P
end
end
local gQ=dQ.rec
local hQ=dQ.p0 or W.PRIOR_WIN[dQ.kind]or 0.7
local iQ=W.sim(dQ)
if iQ and not(iQ.trust and not iQ.trust.ok)then
local jQ=iQ.calibrated or gQ.runs>0
local kQ=(iQ.trust and iQ.trust.ok)and 6 or(jQ and 3 or 1.5)
local lQ=(jQ or iQ.hopeless)and 0 or 2
local mQ,nQ=pcall(gb.styleP,iQ)
return(gQ.wins+hQ*lQ+(mQ and nQ or iQ.p)*kQ)/(gQ.runs+lQ+kQ)
end
return(gQ.wins+hQ*2)/(gQ.runs+2)
end
function W.minutes(oQ)
