function W.score(zQ)
local AQ,BQ=((zQ.kind==CBe[2182]and zQ.rec.runs>0)or zQ.kind==CBe[2184]or zQ.kind==CBe[2619])and 1 or(zQ.kind==CBe[2185]and zQ.p0)or W.winP(zQ),W.minutes(zQ)
