if CQ and(DQ or 0)>0 then
zQ.teamBonus=DQ
if not tostring(zQ.why):find(CBe[2897],1,true)then
zQ.why=(zQ.why or CBe[1078])..CBe[2542]..EQ
end
end
local FQ,GQ,HQ=pcall(W.questValue,zQ)
if FQ and(GQ or 0)>0 then
zQ.questBonus=GQ
if HQ and not tostring(zQ.why):find(HQ,1,true)then
zQ.why=(zQ.why or CBe[1078])..CBe[2542]..HQ
end
else
zQ.questBonus=nil
end
local IQ=AQ*(zQ.value+(zQ.teamBonus or 0)+(zQ.questBonus or 0))/BQ
zQ.baseScore=IQ
local JQ,KQ,LQ=pcall(ib.valueFor,zQ)
if JQ and KQ>0 then
local MQ=AQ*(zQ.value+KQ)/(BQ*LQ)
if MQ>IQ then
IQ,zQ.train=MQ,KQ
end
end
if zQ.rec.runs<2 then
IQ=IQ*(1+O.exploreBonus)
end
return IQ
end
