local Acb,Bcb=0,nil
local Ccb={}
for Dcb,Ecb in ipairs(V.equipped())do
Ccb[Ecb.uuid]=true
end
for Fcb,Gcb in pairs(ccb)do
if Gcb._equipped_relic then
Acb=Acb+1
if not Ccb[Fcb]and(not Bcb or not table.find(P.str.core or{},Fcb))then
Bcb=Gcb._equipped_relic
end
end
end
if Acb>=kb.MAX_RELICS and Bcb and not jcb(Bcb)then
return false
end
local Hcb=U.now()
F.request(CBe[3207],CBe[2696],zcb,{unit_uuid=ycb.e.uuid})
while U.now()-Hcb<4 and ycb.e.u._equipped_relic~=zcb do
task.wait(0.25)
end
task.wait(1.2)
if ycb.e.u._equipped_relic~=zcb then
F.log(1,CBe[3190],string.format(CBe[3211],(N.Items[(bcb.inventory:get_item_by_uuid(zcb)or{}).item_id]or{}).name or CBe[3212],V.name(ycb.e.id),hcb(Hcb)))
F.backoff(CBe[3207],300)
P.str.relicAt=0
return false
end
wcb=wcb+1
end
end
W._sigAt=nil
P.str.relicSig=W.teamSig()
P.str.relicTeam=P.str.relicSig
P.str.relicNote=string.format(CBe[3213],Zbb)
kb.note(string.format(CBe[3214],wcb,Zbb))
