end
for bdb,cdb in ipairs(Xcb)do
local ddb=Vcb.collection:get_unit_by_uuid(cdb)
if ddb then
local edb,fdb=ddb.unit_id,V.name(ddb.unit_id)
if O.teamXp and Zcb>0 then
local gdb,hdb=kb.gainXp(ddb,Zcb)
local idb,jdb=kb.gainXp(ddb,500000)
local kdb=jdb>0 and idb/jdb*hdb or 0
if hdb>0 and kdb>0 then
local ldb=kb.feedPlan(ddb)
local mdb,ndb=kb.level(ddb),kb.level({unit_id=edb,xp=(tonumber(ddb.xp)or 0)+hdb})
table.insert(Wcb,{kind=CBe[3216],uuid=cdb,name=fdb,gain=kdb,add=hdb,planned=ldb.planned,items=ldb.n,lvl0=mdb,lvl1=kb.level({unit_id=edb,xp=(tonumber(ddb.xp)or 0)+(ldb.planned>0 and ldb.planned or hdb)}),text=string.format(CBe[3217],fdb,U.fmt(hdb),ndb>mdb and string.format(CBe[3218],mdb,ndb)or string.format(CBe[3219],mdb),kdb)})
end
end
end
end
table.sort(Wcb,function(odb,pdb)
if odb.gain~=pdb.gain then
return odb.gain>pdb.gain
end
return odb.text<pdb.text
end)
for qdb in pairs(V._mult)do
if type(qdb)==CBe[1064]and qdb:sub(1,5)==CBe[3193]then
V._mult[qdb]=nil
