table.insert(P.str.acts,{kind=sdb.kind,uuid=sdb.uuid,name=sdb.name,gain=sdb.gain,text=sdb.text,blocked=sdb.blocked,add=sdb.add,planned=sdb.planned,items=sdb.items,lvl0=sdb.lvl0,lvl1=sdb.lvl1})
end
