end
function kb.xpRate()
local tdb=N.session()
if not tdb then
return 0
end
local udb=0
for vdb,wdb in ipairs(kb.core())do
local xdb=tdb.collection:get_unit_by_uuid(wdb)
if xdb then
local ydb,zdb=kb.gainXp(xdb,500000)
if zdb>0 then
udb=math.max(udb,ydb/zdb)
end
end
end
local Adb=udb*(O.strengthValue or 300)
if(tonumber(N.cur(CBe[2231]))or 0)>(O.xpGoldFloor or 100000)then
Adb=math.min(Adb,(N.GOLD_VALUE or 0.02)/14)
end
return Adb
end
function kb.xpGuess(Bdb)
local Cdb=Bdb.level and N.Levels[Bdb.level]
if not Cdb then
return 0
end
local Ddb=math.min(9,tonumber(Cdb.story_world_rank)or tonumber(Bdb.rank)or 9)
local Edb=tonumber(Cdb.story_level_rank)or 6
local Fdb=(Bdb.kind==CBe[2205]and 1.5 or 1)*(Ddb>5 and 2 or 1)
local Gdb=2.1564^(Ddb-1)*(40+10*Edb)/Fdb
if Bdb.kind==CBe[2184]then
Gdb=3*30*2.1564^(Ddb-1)/Fdb
end
local Hdb=Ddb>=9 and 0.3 or(Ddb>=7 and 0.5 or 1)
return Gdb*Hdb*6
end
function kb.modeBonus(Idb)
if not(O.team and O.teamXp)or Idb.kind==CBe[2185]or Idb.kind==CBe[2182]then
return 0
end
local Jdb=kb._xpRate and os.time()-(kb._xpRateAt or 0)<300 and kb._xpRate or nil
if not Jdb then
Jdb=kb.xpRate()
kb._xpRate,kb._xpRateAt=Jdb,os.time()
end
if Jdb<=0 then
return 0
end
local Kdb=P.modes and P.modes[Idb.key]
local Ldb=tonumber(Kdb and Kdb.xp)or kb.xpGuess(Idb)
local Mdb=Ldb*Jdb
if Mdb<1 then
return 0
end
return Mdb,string.format(CBe[3220],U.fmt(Ldb),math.floor(Mdb+0.5))
end
function kb.xpSettle()
local Ndb=P.lastRun
if not(Ndb and type(Ndb.xp0)==CBe[2159]and Ndb.key)then
return
end
local Odb=N.session()
if not Odb then
return
end
local Pdb,Qdb=0,0
for Rdb,Sdb in pairs(Ndb.xp0)do
local Tdb=Odb.collection:get_unit_by_uuid(Rdb)
if Tdb then
Pdb=Pdb+math.max(0,(tonumber(Tdb.xp)or 0)-(tonumber(Sdb)or 0))
Qdb=Qdb+1
end
end
P.lastRun=nil
if Qdb==0 then
return
end
local Udb=W.rec(Ndb.key)
Udb.xp=Udb.xp and(Udb.xp+(Pdb-Udb.xp)*0.3)or Pdb
if Pdb>0 then
F.log(2,kb.LOG,string.format(CBe[3221],Ndb.key,U.fmt(Pdb)))
end
F.saveSoon()
