if Web then
return CBe[3237]..((N.Items[Web.item]or{}).name or Web.item)..CBe[3238]..V.name(Veb.from)..CBe[3236],CBe[2264]
end
end
if ab.snipeWanted()then
return CBe[3239]..V.name(O.snipeUnit)..CBe[3240],CBe[3241]
end
if ab.snipeDue()then
