end
local Vfb=string.format(CBe[3278],V.name(Cfb.from),V.name(Cfb.to),U.fmt(Cfb.scoreFrom or 0),U.fmt(Cfb.scoreTo or 0))
cb.add(CBe[3279]..Vfb,1,CBe[3280],(Dfb or CBe[3281])..(#Qfb>0 and(CBe[3282]..table.concat(Qfb,CBe[2280]))or CBe[1078]))
F.log(1,CBe[3283],Vfb..CBe[3284]..(Dfb or CBe[3281])..(#Qfb>0 and(CBe[3282]..table.concat(Qfb,CBe[2280]))or CBe[1078]))
W._sigAt=nil
pcall(hb.refresh)
return true,V.name(Cfb.to)..CBe[3285]
end
F.log(1,CBe[3283],CBe[3286]..V.name(Cfb.from)..CBe[2858]..tostring(Lfb)..CBe[3287]..tostring(Mfb and Mfb.unit_id))
return false,CBe[3288]..tostring(Lfb)..CBe[2830]
