oIb=FIb
end
end
end
local GIb=math.max(1,hIb.incomeRate or 20)
local HIb=hIb.waveSec or 20
local function IIb(JIb,KIb,LIb)
local MIb=math.max(0,(JIb.cost-hIb.money)/GIb)
local NIb=JIb.gain*math.max(0,LIb-MIb)
