for omc,pmc in ipairs(V.equipped())do
local qmc=pmc.id or(pmc.u and pmc.u.unit_id)
if qmc and pmc.u and not V.isFarm(qmc)and not V.allyBuff(qmc)then
local rmc=V.rows(qmc)
local smc,tmc=pcall(V.dps,pmc.u,rmc and rmc.max or 0,nil)
tmc=smc and tonumber(tmc)or 0
local umc,vmc=V.types(qmc)
mmc=mmc+tmc
if vmc==lmc or vmc==lmc..CBe[2370]then
nmc=nmc+tmc
