zmc=zmc+120
end
for Cmc,Dmc in pairs(type(ymc.wave_modifier_effects)==CBe[2159]and ymc.wave_modifier_effects or{})do
local Emc=math.abs(tonumber(Dmc.amount)or 0)
if Dmc.type==CBe[4145]and Dmc.stat==CBe[2601]then
zmc=zmc+100*Emc
elseif Dmc.type==CBe[4145]and Dmc.stat==CBe[2602]then
zmc=zmc+100*Emc/math.max(0.2,1-Emc)
elseif Dmc.type==CBe[4145]and Dmc.stat==CBe[2419]then
zmc=zmc+50*Emc
elseif Dmc.type==CBe[4146]and Dmc.stat==CBe[4147]then
zmc=zmc+100*Emc*jb.share(CBe[2341])
elseif Dmc.type==CBe[4146]and Dmc.stat==CBe[4148]then
zmc=zmc+100*Emc*jb.share(CBe[2339])
elseif Dmc.type==CBe[4146]and Dmc.stat==CBe[4149]then
zmc=zmc+100*Emc*jb.share(CBe[4001])
elseif Dmc.type==CBe[4150]and Dmc.stat==CBe[4151]then
zmc=zmc+60*Emc*jb.share(CBe[2341])
elseif Dmc.type==CBe[4152]then
zmc=zmc+40*Emc
elseif Dmc.type==CBe[4153]then
zmc=zmc+80*Emc
elseif Dmc.type==CBe[4154]then
zmc=zmc+80*Emc
end
end
return zmc
end
jb.CURSE_COST={_curse_money=0.5,_curse_shop=0.5,_curse_health=0.5,_curse_speed=0.5,_curse_regen=0.5,_curse_shield=1,_curse_explode=1.5,_curse_random=2,_curse_super_health=1,_curse_super_speed=1,_curse_super_regen=1,_curse_super_armored=3,_curse_super_burst=1,_curse_super_explode=3,_curse_super_chaos=3}
function jb.curseCost(Fmc)
if Fmc==CBe[4155]then
local Gmc,Hmc=0,0
for Imc,Jmc in ipairs(V.equipped())do
local Kmc=Jmc.id or(Jmc.u and Jmc.u.unit_id)
if Kmc and not V.isFarm(Kmc)then
Gmc=Gmc+1
local Lmc,Mmc=pcall(V.airFrom,Kmc)
if Lmc and Mmc then
Hmc=Hmc+(Mmc==0 and 1 or 0.5)
end
end
end
return 1+2*(Gmc>0 and 1-Hmc/Gmc or 0.5)
end
return jb.CURSE_COST[Fmc]or 1.5
end
function jb.roomValue(Nmc,Omc)
local Pmc,Qmc=Nmc.tags,Nmc.d
local Rmc=0
if Pmc[jb.T.GOLD]then
Rmc=Rmc+12
end
if Pmc[jb.T.CHEST]then
Rmc=Rmc+4
end
if Pmc[jb.T.MONEY]then
Rmc=Rmc+(Qmc<=15 and 2 or 0.5)
end
if Pmc[jb.T.SHOP]then
if Qmc>=10 and Qmc<=15 then
Rmc=Rmc+(Omc>=300 and 5 or 1)
else
Rmc=Rmc+(Omc>=300 and(Qmc>15 and 3 or 1)or 0.3)
end
end
if Pmc[jb.T.SHRINE]then
Rmc=Rmc+1.5
end
if Pmc[jb.T.CURSE]then
Rmc=Rmc-jb.curseCost(jb.roomCurse(Nmc.r))
end
return Rmc
end
function jb.mod(Smc)
