function bb.infStop(yxc)
local zxc=0
for Axc,Bxc in ipairs(U.list(N.GS.DAILY_INFINITE_REWARDS))do
zxc=math.max(zxc,tonumber(Bxc.wave)or 0)
end
if zxc<=0 or yxc<=zxc+1 then
return
end
local Cxc=P.train.on
if bb.trainee and Cxc and Cxc.have+(Cxc.got or 0)+(bb.trainTk or 0)<Cxc.need then
return
end
if not ab.every(CBe[4322],60)then
return
end
local Dxc=W.rec(bb.key)
local Exc=tonumber(Dxc.timed)or 0
local Fxc=W.INF_PAY
local Gxc
if yxc>=(Fxc.cap+Fxc.less)/Fxc.per then
Gxc=0
else
local Hxc=bb.infWaveAt or{}
local Ixc,Jxc=Hxc[yxc],Hxc[yxc-5]
if Ixc and Jxc and Ixc>Jxc then
Gxc=Fxc.per*5/((Ixc-Jxc)/60)
end
if not Gxc then
Gxc=(Exc>0 and(Dxc.sec or 0)>0)and math.max(0.5,(Dxc.gems or 0)/(Dxc.sec/60))or 2.5
end
end
