for Mxc,Nxc in ipairs(Kxc and W.lastScored or{})do
if Nxc.kind~=CBe[2184]and(not Lxc or(Nxc.score or 0)>(Lxc.score or 0))then
Lxc=Nxc
end
end
if not Lxc or(Lxc.score or 0)<=Gxc then
return
end
bb.stopping=true
F.log(1,CBe[2837],string.format(CBe[4323],yxc,Gxc,Lxc.score,Lxc.label))
bb.sellAll()
end
function bb.trainLeave(Oxc)
