function bb.valid(aAc,bAc,cAc)
local dAc=N.PC.raycast(aAc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not dAc then
return nil
end
if not N.PC.is_valid_raycast_hit(dAc.Instance,bAc)then
return nil
end
local eAc=dAc.Position
if bb.blockedSpot(eAc)then
return nil
end
local fAc=(tonumber(bAc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(fAc*2,2.5,fAc*2)
bb.probe.CFrame=CFrame.new(eAc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
local gAc=U.flat(eAc)
local hAc=bb.grifZone
if hAc and type(bAc)==CBe[2159]and bAc.id~=V.GRIF.egg and not V.sacFodder(bAc.id)and(gAc-hAc.p).Magnitude<=hAc.r+1.5 then
return nil
end
for iAc,jAc in ipairs(bb.mine or{})do
local kAc=jAc:FindFirstChild(CBe[4346])
local lAc=kAc and kAc.Position or jAc:GetPivot().Position
local mAc=kAc and math.max(kAc.Size.X,kAc.Size.Z)/2 or 1.5
if(gAc-U.flat(lAc)).Magnitude<fAc+mAc then
return nil
end
end
if not cAc then
for nAc,oAc in ipairs(bb.blockers())do
if(gAc-oAc.p).Magnitude<fAc+oAc.r then
return nil
end
end
end
return eAc
end
function bb.buildCandidates()
bb.cands={}
local pAc={}
for qAc=1,#bb.samples,3 do
local rAc=bb.samples[qAc]
local sAc=bb.samples[math.min(#bb.samples,qAc+1)]
local tAc=U.flat(sAc.pos-rAc.pos)
if tAc.Magnitude<0.01 then
tAc=Vector3 .new(1,0,0)
end
tAc=tAc.Unit
local uAc=Vector3 .new(-tAc.Z,0,tAc.X)
for vAc,wAc in ipairs({3,4.5,6,8,10.5,13.5,17})do
for xAc,yAc in ipairs({1,-1})do
local zAc=rAc.pos+uAc*wAc*yAc
local AAc=string.format(CBe[4343],math.floor(zAc.X/1.5),math.floor(zAc.Z/1.5))
if not pAc[AAc]then
pAc[AAc]=true
table.insert(bb.cands,zAc)
end
end
end
end
end
function bb.coverage(BAc,CAc)
local DAc={}
for EAc,FAc in ipairs(BAc)do
local GAc=FAc._stats
if not V.isFarm(GAc.id.Value)and GAc:FindFirstChild(CBe[2419])then
table.insert(DAc,{p=U.flat(FAc:GetPivot().Position),r=GAc.range.Value*(V.SUMMONER[GAc.id.Value]and V.SUMMONER[GAc.id.Value].reach or 1),air=bb.canAir(FAc)})
end
end
local HAc,IAc=0,0
if#DAc>0 then
for JAc,KAc in ipairs(bb.samples)do
if KAc.prog>IAc then
local LAc=U.flat(KAc.pos)
for MAc,NAc in ipairs(DAc)do
if(LAc-NAc.p).Magnitude<=NAc.r then
if KAc.prog>HAc then
HAc=KAc.prog
end
if NAc.air then
IAc=KAc.prog
break
end
end
end
end
end
end
local OAc,PAc={},bb.laneCount
if PAc and PAc.n>=2 and#DAc>0 then
local QAc={}
for RAc,SAc in ipairs(bb.samples)do
local TAc=U.flat(SAc.pos)
for UAc,VAc in ipairs(DAc)do
if(TAc-VAc.p).Magnitude<=VAc.r then
local WAc=tostring(SAc.lane)
QAc[WAc]=(QAc[WAc]or 0)+1
if SAc.prog>(OAc[WAc]or 0)then
OAc[WAc]=SAc.prog
end
break
end
end
end
local XAc,YAc={},0
for ZAc,_Ac in pairs(PAc.by)do
XAc[ZAc]=(QAc[ZAc]or 0)/math.max(1,_Ac)
YAc=math.max(YAc,XAc[ZAc])
end
bb.laneW={}
for aBc,bBc in pairs(PAc.by)do
bb.laneW[aBc]=(PAc.avg/math.max(1,bBc))*(1+1.5*(YAc>0 and(1-XAc[aBc]/YAc)or 0))
end
bb.laneFrac=XAc
else
bb.laneW,bb.laneFrac=nil,nil
end
local cBc,dBc,eBc
if#DAc>0 then
for fBc,gBc in ipairs(CAc)do
local hBc=(bb.laneW and gBc.lane)and(OAc[tostring(gBc.lane)]or 0)or HAc
if gBc.hp>0 and gBc.prog>hBc+0.02 and gBc.prog>(cBc or 0)then
cBc,eBc=gBc.prog,bb.laneW and gBc.lane or nil
end
if gBc.hp>0 and gBc.fly and gBc.prog>IAc+0.02 then
dBc=true
end
end
end
local iBc= #DAc>0 and(bb.pressure or 0)>=HAc-0.08
return{covEnd=HAc,airEnd=IAc,leak=cBc,leakLane=eBc,covL=OAc,airLeak=dBc,push=iBc,units= #DAc}
end
function bb.needLastLine(jBc)
if V.isFarm(jBc.id)or V.allyBuff(jBc.id)or bb.fieldCount()<5 then
return false
end
local kBc,lBc=0,0
for mBc,nBc in ipairs(bb.mine or{})do
local oBc=nBc._stats
if not V.isFarm(oBc.id.Value)and oBc:FindFirstChild(CBe[2419])then
