end
table.insert(QUc.wave,tonumber(TUc)or 0)
if tonumber(UUc)then
QUc.kills=type(QUc.kills)==CBe[2159]and QUc.kills or{}
table.insert(QUc.kills,math.floor(tonumber(UUc)))
while#QUc.kills>bb.LAYOUT_KEEP do
table.remove(QUc.kills,1)
end
end
while#QUc.sec>bb.LAYOUT_KEEP do
table.remove(QUc.sec,1)
end
while#QUc.wave>bb.LAYOUT_KEEP do
