bb.CONTROL_WORDS={CBe[4521],CBe[4522],CBe[4523],CBe[4524]}
function bb.controlSpot(EVc,FVc)
if not bb.killZone()then
return nil
end
local GVc=gb.holds
if not GVc(EVc.id)or V.toggleOf(EVc.id)then
return nil
end
local HVc,IVc,JVc,KVc=1,0,0,{}
local LVc=bb.hurtSamples()
for MVc,NVc in ipairs(bb.mine or{})do
local OVc=NVc._stats
local PVc=OVc.id.Value
if OVc:FindFirstChild(CBe[2419])and not V.isFarm(PVc)and not V.allyBuff(PVc)then
local QVc,RVc=U.flat(NVc:GetPivot().Position),OVc.range.Value
if GVc(PVc)and not V.toggleOf(PVc)then
JVc=JVc+1
table.insert(KVc,{p=QVc,r=RVc})
else
for SVc,TVc in ipairs(LVc)do
if(U.flat(TVc.pos)-QVc).Magnitude<=RVc then
HVc,IVc=math.min(HVc,TVc.prog),math.max(IVc,TVc.prog)
end
end
end
end
end
if IVc<=HVc then
HVc,IVc=0.75,0.98
end
local UVc=(FVc or JVc)+1
local VVc=({HVc,IVc,(HVc+IVc)/2,HVc-(IVc-HVc)/2})[UVc]
if not VVc then
return nil
end
local WVc=V.range(EVc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local XVc={}
for YVc,ZVc in ipairs(bb.cands)do
local _Vc,aWc,bWc=U.flat(ZVc),0,0
for cWc,dWc in ipairs(LVc)do
if(U.flat(dWc.pos)-_Vc).Magnitude<=WVc then
bWc=bWc+1
if math.abs(dWc.prog-VVc)<=0.05 then
aWc=aWc+1
local eWc=U.flat(dWc.pos)
for fWc,gWc in ipairs(KVc)do
if(eWc-gWc.p).Magnitude<=gWc.r then
aWc=aWc-0.5
break
end
end
end
end
end
if aWc>0 then
table.insert(XVc,{pos=ZVc,sc=aWc,cov=bWc})
end
if YVc%60==0 then
task.wait()
end
end
table.sort(XVc,function(hWc,iWc)
return hWc.sc>iWc.sc
end)
for jWc,kWc in ipairs(XVc)do
local lWc=bb.valid(kWc.pos,EVc.data)
if lWc then
F.log(1,CBe[4350],string.format(CBe[4525],V.name(EVc.id),bb.CONTROL_WORDS[UVc],math.floor(VVc*100+0.5)))
return lWc,kWc.cov,VVc
end
if jWc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(mWc)
local nWc,oWc=gb.holds(mWc.id)
if not nWc then
return nil
end
if V.killFed(mWc.id)then
return nil
end
local pWc,qWc={},0
for rWc,sWc in ipairs(bb.mine or{})do
local tWc=sWc._stats
local uWc=tWc.id.Value
if tWc:FindFirstChild(CBe[2419])and not V.isFarm(uWc)and not V.allyBuff(uWc)and uWc~=mWc.id then
local vWc,wWc=pcall(bb.liveDps,sWc,uWc)
wWc=vWc and tonumber(wWc)or 0
if wWc>0 then
table.insert(pWc,{p=U.flat(sWc:GetPivot().Position),r=tWc.range.Value,d=wWc})
qWc=qWc+wWc
end
end
end
if#pWc==0 or qWc<=0 then
return nil
end
local xWc=bb.hurtSamples()
local yWc={}
for zWc,AWc in ipairs(xWc)do
local BWc,CWc=U.flat(AWc.pos),0
for DWc,EWc in ipairs(pWc)do
if(BWc-EWc.p).Magnitude<=EWc.r then
CWc=CWc+EWc.d
end
end
yWc[zWc]=CWc/qWc
end
local FWc=V.range(mWc.u,math.min(tonumber(oWc)or 0,3,V.rows(mWc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local GWc,HWc,IWc
for JWc,KWc in ipairs(bb.cands)do
local LWc,MWc,NWc=U.flat(KWc),0,0
for OWc,PWc in ipairs(xWc)do
if(U.flat(PWc.pos)-LWc).Magnitude<=FWc then
MWc=MWc+yWc[OWc]
NWc=NWc+1
end
end
if MWc>0 and(not HWc or MWc>HWc)then
local QWc=bb.valid(KWc,mWc.data)
if QWc then
GWc,HWc,IWc=QWc,MWc,NWc
end
end
if JWc%40==0 then
task.wait()
end
end
if not GWc then
return nil
end
bb.holdSaid=bb.holdSaid or{}
if not bb.holdSaid[mWc.id]then
bb.holdSaid[mWc.id]=true
F.log(1,CBe[4350],string.format(CBe[4526],V.name(mWc.id)))
end
return GWc,IWc or 0
end
function bb.bestSpot(RWc,SWc,TWc)
if(RWc._grif or RWc.id==V.GRIF.egg)and not TWc and bb.grifOn()then
local UWc,VWc,WWc=pcall(bb.grifSpot,RWc)
if UWc and VWc then
return VWc,WWc
