if not V.isFarm(sid.id)then
qid[sid.id]=(qid[sid.id]or 0)+(tonumber(sid.v)or 0)
end
end
for tid,vid in pairs(bb.helperDealt or{})do
if vid.owner and V.SUMMONER[vid.owner]and not V.droneHelper(vid)then
qid[vid.owner]=(qid[vid.owner]or 0)+(tonumber(vid.v)or 0)
end
end
local wid=type(bb.calRun.potExp)==CBe[2159]and bb.calRun.potExp or{}
local xid,yid=0,0
local zid={}
for Aid,Bid in pairs(oid)do
if Bid>0 then
xid,yid=xid+(qid[Aid]or 0),yid+Bid
local Cid=tonumber(wid[Aid])or Bid
if Cid>0 then
table.insert(zid,{id=Aid,r=(qid[Aid]or 0)/Cid,w=Cid})
end
end
end
if xid<=0 or yid<=0 then
return
end
table.sort(zid,function(Did,Eid)
return Did.r<Eid.r
end)
local function Fid(Gid)
local Hid,Iid=0,0
for Jid,Kid in ipairs(zid)do
if Kid.id~=Gid then
Hid=Hid+Kid.w
end
end
if Hid<=0 then
return nil
end
for Lid,Mid in ipairs(zid)do
if Mid.id~=Gid then
Iid=Iid+Mid.w
if Iid>=Hid/2 then
return Mid.r
end
end
end
end
bb.lastEff={}
for Nid,Oid in pairs(oid)do
local Pid=Fid(Nid)
if Oid>0 and Oid/yid>0.02 and Pid and Pid>0 then
local Qid=P.learn[Nid]or{eff=1,n=0,v=6}
V.learnUp(Nid,Qid)
local Rid=math.max(0.02,0.25*math.sqrt(30/(30+Qid.n)))
local Sid=U.clamp(((qid[Nid]or 0)/Oid)/Pid,0.2,6)
bb.lastEff[Nid]=math.floor(Sid*1000+0.5)/1000
Qid.eff=Qid.eff+(Sid-Qid.eff)*Rid
Qid.n=Qid.n+1
P.learn[Nid]=Qid
end
end
local Tid=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if Tid and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==CBe[2159]and P.mapLearn or{}
local Uid=type(P.mapLearn[Tid])==CBe[2159]and P.mapLearn[Tid]or{}
for Vid,Wid in pairs(bb.lastEff)do
local Xid=type(Uid[Vid])==CBe[2159]and Uid[Vid]or{eff=Wid,n=0,v=6}
if(tonumber(Xid.v)or 0)<4 then
Xid.eff,Xid.v=(tonumber(Xid.eff)or Wid)*V.secRescale(Vid),4
end
if(tonumber(Xid.v)or 0)<5 then
Xid.eff,Xid.v=(tonumber(Xid.eff)or Wid)*(V.sumRescale(Vid)or 1),5
end
if(tonumber(Xid.v)or 0)<6 then
Xid.eff,Xid.v=(tonumber(Xid.eff)or Wid)*(1-(V.SUMMONER[Vid]and V.SUMMONER[Vid].droneShare or 0)),6
end
local Yid=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(Xid.n)or 0))))
Xid.eff=(tonumber(Xid.n)or 0)==0 and Wid or((tonumber(Xid.eff)or Wid)+(Wid-(tonumber(Xid.eff)or Wid))*Yid)
Xid.n=(tonumber(Xid.n)or 0)+1
Uid[Vid]=Xid
end
Uid._at=os.time()
P.mapLearn[Tid]=Uid
if U.count(P.mapLearn)>80 then
local Zid,ajd
for bjd,cjd in pairs(P.mapLearn)do
if not ajd or(tonumber(cjd._at)or 0)<ajd then
Zid,ajd=bjd,tonumber(cjd._at)or 0
end
end
P.mapLearn[Zid]=nil
end
end
end
function bb.randomTeam()
