function bb.cardDps(Gkd)
local Hkd,Ikd=pcall(V.dps,Gkd.u,0,bb.mod)
Ikd=Hkd and tonumber(Ikd)or 0
if Ikd>0 or V.isFarm(Gkd.id)or V.idol(Gkd.id)or V.allyBuff(Gkd.id)then
return Ikd
end
local Jkd=table.clone(bb.cardVals or{})
if#Jkd==0 then
return 1000
end
table.sort(Jkd)
return Jkd[math.max(1,math.ceil(#Jkd*0.6))]
end
function bb.cardValue(Kkd)
if V.isFarm(Kkd.id)then
return 0
end
if V.idol(Kkd.id)then
return(bb.teamDps or 0)*bb.idolStep()*3
end
local Lkd=V.allyBuff(Kkd.id)and bb.buffGain(Kkd)or bb.cardDps(Kkd)
return Lkd*(1+2*bb.carry(Kkd.id))*(1-bb.resistOf(Kkd.id))*bb.airNeed(Kkd.id)*(bb.mergeIds[Kkd.id]and 2 or 1)
end
