if bb._curseFly==nil then
local Mkd,Nkd=pcall(jb.items,jb.data())
bb._curseFly=Mkd and(Nkd._curse_fly or 0)>0 or false
end
return bb._curseFly
end
return false
end
function bb.shieldNow()
local Okd=bb.wave()
if bb._shieldW~=Okd then
bb._shieldW,bb._shieldS,bb._shieldH=Okd,0,1
local Pkd,Qkd=pcall(gb.wave,bb.info,math.max(1,Okd),true)
if bb.info and Pkd and#Qkd>0 then
local Rkd,Skd=0,0
for Tkd,Ukd in ipairs(Qkd)do
Rkd,Skd=Rkd+(Ukd.sh or 0),Skd+Ukd.hp
end
bb._shieldS,bb._shieldH=Rkd/ #Qkd,Skd/ #Qkd
end
end
return bb._shieldS,bb._shieldH
end
function bb.shieldOf(Vkd,Wkd)
local Xkd,Ykd=bb.shieldNow()
if Xkd<=0 or not Wkd then
return Vkd
end
local Zkd=V.attackInfo(Wkd.atk,Wkd.range)
return eb.shieldDps(Vkd,tonumber(Wkd.cd)or 2,Zkd.n,Xkd,Ykd,bb.info and bb.info.eff,Zkd.hits)
