function bb.shieldWork(_kd,ald)
local bld,cld=bb.shieldNow()
if bld<=0 or not ald or not bb.info then
return 0
end
local dld,eld=0,0
for fld,gld in ipairs(bb.team or{})do
local hld=V.rows(gld.id)
hld=hld and hld[0]
if hld and not V.isFarm(gld.id)then
dld=math.max(dld,V.dps(gld.u,0,bb.mod)*(tonumber(hld.cd)or 2)/math.max(1,V.attackInfo(hld.atk,hld.range).n))
end
end
for ild,jld in ipairs(bb.mine or{})do
local kld=jld._stats.id.Value
local lld=V.rows(kld)
local mld=lld and lld[jld._stats.upgrade and jld._stats.upgrade.Value or 0]
if mld and not V.isFarm(kld)and not V.allyBuff(kld)then
local nld=V.attackInfo(mld.atk,mld.range)
eld=eld+nld.n*nld.hits/math.max(0.3,tonumber(mld.cd)or 2)
end
end
local pld,qld=pcall(gb.wave,bb.info,math.max(1,bb.wave()),true)
local rld=V.attackInfo(ald.atk,ald.range)
return eb.shieldWork(rld.n,tonumber(ald.cd)or 2,eld,bld,pld and#qld or 1,bb.info.waveSec,dld*(bb.info.eff or 1),cld,rld.hits)
