if _ld then
Xld=true
end
local amd=bb.roomPlan and bb.roomPlan.name==V.name(Zld.id)
local bmd=(bb.noSpot[Zld.uuid]or 0)>=3
local cmd=not bmd and(_ld or amd or V.idol(Zld.id)or bb.mergeIds[Zld.id])
local dmd=U.now()-(tonumber(bb.cardSeen[Zld.uuid])or U.now())>60
