function bb.baseVerdict(kpd,lpd)
local mpd=(lpd.t or 0)-(kpd.t or 0)
if mpd<bb.BASE_WIN-1 then
return false
end
local npd=((tonumber(kpd.base)or 0)-(tonumber(lpd.base)or 0))/mpd
if npd<=0 or(tonumber(lpd.base)or 0)<=0 then
return false
end
local opd=lpd.base/npd
local ppd,qpd=0,0
local rpd,spd=kpd.foes or{},lpd.foes or{}
for tpd,upd in pairs(spd)do
if upd.prog>=bb.BASE_END then
ppd=ppd+upd.hp
local vpd=rpd[tpd]
if vpd then
qpd=qpd+math.max(0,vpd.hp-upd.hp)
end
end
end
for wpd,xpd in pairs(rpd)do
if xpd.prog>=bb.BASE_END and not spd[wpd]then
qpd=qpd+xpd.hp
end
end
if ppd<=0 then
return false
end
local ypd=qpd/mpd
local zpd=ypd>0 and ppd/ypd or math.huge
local Apd={baseTime=opd,loss=npd,atEnd=ppd,rate=ypd,killTime=zpd}
return opd<bb.BASE_SOON and zpd>opd*bb.BASE_MARGIN,Apd
end
